package rotator

import (
	"encoding/json"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"sort"
	"strings"
	"testing"

	"github.com/simtabi/ssh-manager/src/v3/internal/core/inventory"
	"github.com/simtabi/ssh-manager/src/v3/internal/core/manifest"
	"github.com/simtabi/ssh-manager/src/v3/internal/services/reconciler"
	"github.com/simtabi/ssh-manager/src/v3/internal/util/paths"
)

// fakeOpScript is a stateful stand-in for the 1Password CLI: one directory per
// item (title, id, a real Ed25519 public key generated by ssh-keygen), and an
// archive directory for archived items. It answers only the calls sshmgr makes.
const fakeOpScript = `#!/bin/sh
V="$FAKE_OP_VAULT"; mkdir -p "$V/items" "$V/archive"
cmd="$1 $2"; shift 2
json() { d="$1"; printf '{"id":"%s","title":"%s","vault":{"name":"V"},"fields":[{"id":"public_key","label":"public key","value":"%s"}]}\n' "$(cat $d/id)" "$(cat $d/title)" "$(cat $d/pub)"; }
find_title() { for d in "$V"/items/*; do [ -d "$d" ] && [ "$(cat $d/title)" = "$1" ] && echo "$d"; done; }
case "$cmd" in
"item create")
  title=""; while [ $# -gt 0 ]; do [ "$1" = "--title" ] && title="$2"; shift; done
  id="i$(ls "$V/items" "$V/archive" | wc -l | tr -d ' ')$$"; d="$V/items/$id"; mkdir -p "$d"
  ssh-keygen -q -t ed25519 -N '' -C "$title" -f "$d/k" >/dev/null
  echo "$id" > "$d/id"; echo "$title" > "$d/title"; cut -d' ' -f1,2 "$d/k.pub" > "$d/pub"; rm -f "$d/k"
  json "$d" ;;
"item get")
  d=$(find_title "$1"); [ -z "$d" ] && { echo "[ERROR] \"$1\" isn't an item in the vault." >&2; exit 1; }
  json "$d" ;;
"item edit")
  id="$1"; shift; while [ $# -gt 0 ]; do [ "$1" = "--title" ] && echo "$2" > "$V/items/$id/title"; shift; done ;;
"item delete")
  mv "$V/items/$1" "$V/archive/$1" ;;
*) echo "fake op: unsupported $cmd" >&2; exit 2 ;;
esac
`

// opVault installs the fake op on PATH and returns a function listing the live
// item titles, sorted.
func opVault(t *testing.T) (titles func() []string, archived func() int) {
	t.Helper()
	if runtime.GOOS == "windows" {
		t.Skip("the fake op is a shell script")
	}
	if _, err := exec.LookPath("ssh-keygen"); err != nil {
		t.Skip("ssh-keygen not on PATH")
	}
	bin := t.TempDir()
	vault := t.TempDir()
	if err := os.WriteFile(filepath.Join(bin, "op"), []byte(fakeOpScript), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH"))
	t.Setenv("FAKE_OP_VAULT", vault)
	titles = func() []string {
		var out []string
		entries, _ := os.ReadDir(filepath.Join(vault, "items"))
		for _, e := range entries {
			b, _ := os.ReadFile(filepath.Join(vault, "items", e.Name(), "title"))
			out = append(out, strings.TrimSpace(string(b)))
		}
		sort.Strings(out)
		return out
	}
	archived = func() int {
		entries, _ := os.ReadDir(filepath.Join(vault, "archive"))
		return len(entries)
	}
	return titles, archived
}

const opManifestJSON = `{"version":1,"defaults":{"key_type":"ed25519","rotate_after_days":365},
  "profiles":{"bot":{"category":"orgs","key_store":"1password","op_vault":"Simtabi","hosts":[
    {"alias":"panel","hostname":"ploi.example","user":"x","provider":"ploi","key_name":"bot_panel-ed25519"}]}}}`

func opSetup(t *testing.T, raw string) (paths.Paths, *manifest.Manifest, *inventory.Inventory) {
	t.Helper()
	var m manifest.Manifest
	if err := json.Unmarshal([]byte(raw), &m); err != nil {
		t.Fatal(err)
	}
	base := t.TempDir()
	return paths.Paths{SSHDir: filepath.Join(base, ".ssh"), ConfigDir: filepath.Join(base, "cfg")}, &m, inventory.New()
}

func TestOnePasswordKeyIsMintedInTheVaultWithOnlyItsPublicHalfOnDisk(t *testing.T) {
	titles, _ := opVault(t)
	p, m, inv := opSetup(t, opManifestJSON)
	if _, err := reconciler.New(p, m, inv, false).Reconcile(false, ""); err != nil {
		t.Fatal(err)
	}
	dir := filepath.Join(p.SSHDir, "profiles", "orgs", "bot")
	if _, err := os.Stat(filepath.Join(dir, "bot_panel-ed25519.pub")); err != nil {
		t.Fatalf("public key not written: %v", err)
	}
	if _, err := os.Stat(filepath.Join(dir, "bot_panel-ed25519")); err == nil {
		t.Fatal("a private key was written to disk for a 1Password profile")
	}
	if got := strings.Join(titles(), ","); got != "bot_panel-ed25519" {
		t.Errorf("vault items = %q", got)
	}
	cfg, _ := os.ReadFile(filepath.Join(p.SSHDir, "profiles", "orgs", "config"))
	if !strings.Contains(string(cfg), "IdentityFile ~/.ssh/profiles/orgs/bot/bot_panel-ed25519.pub\n") ||
		!strings.Contains(string(cfg), "IdentityAgent \"") {
		t.Errorf("rendered host should use the .pub and the 1Password agent:\n%s", cfg)
	}
	// A second reconcile finds the key present: no second item.
	if _, err := reconciler.New(p, m, inv, false).Reconcile(false, ""); err != nil {
		t.Fatal(err)
	}
	if n := len(titles()); n != 1 {
		t.Errorf("reconcile created a duplicate item: %v", titles())
	}
}

func TestOnePasswordRotateThenRollback(t *testing.T) {
	titles, archived := opVault(t)
	p, m, inv := opSetup(t, opManifestJSON)
	if _, err := reconciler.New(p, m, inv, false).Reconcile(false, ""); err != nil {
		t.Fatal(err)
	}
	pub := filepath.Join(p.SSHDir, "profiles", "orgs", "bot", "bot_panel-ed25519.pub")
	before, _ := os.ReadFile(pub)

	rep, err := New(p, m, inv).Rotate("bot_panel-ed25519", true, "")
	if err != nil || !rep.Committed {
		t.Fatalf("rotate: committed=%v err=%v %+v", rep.Committed, err, rep)
	}
	after, _ := os.ReadFile(pub)
	if string(after) == string(before) || rep.OldFingerprint == rep.NewFingerprint {
		t.Fatal("the live public key did not change")
	}
	if got := strings.Join(titles(), ","); got != "bot_panel-ed25519,bot_panel-ed25519.old" {
		t.Errorf("after rotate, vault = %q", got)
	}
	if old, _ := os.ReadFile(filepath.Join(filepath.Dir(pub), "old", "bot_panel-ed25519.pub")); string(old) != string(before) {
		t.Error("the outgoing public key was not archived to old/")
	}

	// A second rotation keeps exactly one predecessor; the older one is archived.
	if rep, err := New(p, m, inv).Rotate("bot_panel-ed25519", true, ""); err != nil || !rep.Committed {
		t.Fatalf("second rotate: %v %+v", err, rep)
	}
	if got := strings.Join(titles(), ","); got != "bot_panel-ed25519,bot_panel-ed25519.old" || archived() != 1 {
		t.Errorf("after two rotations, vault = %q, archived = %d", got, archived())
	}

	mid, _ := os.ReadFile(pub)
	rb, err := New(p, m, inv).Rollback("bot_panel-ed25519")
	if err != nil || !rb.Committed {
		t.Fatalf("rollback: %v %+v", err, rb)
	}
	restored, _ := os.ReadFile(pub)
	if string(restored) == string(mid) {
		t.Error("rollback left the rotated-in public key in place")
	}
	if got := strings.Join(titles(), ","); got != "bot_panel-ed25519" || archived() != 2 {
		t.Errorf("after rollback, vault = %q (want only the restored key), archived = %d", got, archived())
	}
	for _, e := range []string{".staging"} {
		if _, err := os.Stat(filepath.Join(filepath.Dir(pub), e)); err == nil {
			t.Errorf("%s left behind", e)
		}
	}
}

// Switching key_store to 1password and rotating moves the profile into the
// vault: the old key file pair goes to old/, the new key exists only as an item.
func TestRotateMovesAFileKeyIntoOnePassword(t *testing.T) {
	titles, _ := opVault(t)
	fileJSON := strings.Replace(opManifestJSON, `"key_store":"1password","op_vault":"Simtabi",`, "", 1)
	p, m, inv := opSetup(t, fileJSON)
	if _, err := reconciler.New(p, m, inv, false).Reconcile(false, ""); err != nil {
		t.Fatal(err)
	}
	dir := filepath.Join(p.SSHDir, "profiles", "orgs", "bot")
	if _, err := os.Stat(filepath.Join(dir, "bot_panel-ed25519")); err != nil {
		t.Fatalf("file key not minted: %v", err)
	}
	// Switch the store the way an edited manifest would: reload it with the
	// 1Password fields that opManifestJSON carries.
	var switched manifest.Manifest
	if err := json.Unmarshal([]byte(opManifestJSON), &switched); err != nil {
		t.Fatal(err)
	}
	m.Profiles["bot"] = switched.Profiles["bot"]

	rep, err := New(p, m, inv).Rotate("bot_panel-ed25519", true, "")
	if err != nil || !rep.Committed {
		t.Fatalf("rotate: %v %+v", err, rep)
	}
	if _, err := os.Stat(filepath.Join(dir, "bot_panel-ed25519")); err == nil {
		t.Error("the private key file is still at the live path")
	}
	if _, err := os.Stat(filepath.Join(dir, "old", "bot_panel-ed25519")); err != nil {
		t.Errorf("the outgoing key file was not archived to old/: %v", err)
	}
	if got := strings.Join(titles(), ","); got != "bot_panel-ed25519" {
		t.Errorf("vault = %q, want the new key under the live title", got)
	}
	// Rolling back across the move needs the file store again, and says so.
	if _, err := New(p, m, inv).Rollback("bot_panel-ed25519"); err == nil ||
		!strings.Contains(err.Error(), "key_store") {
		t.Errorf("rollback across the move: err = %v, want a pointer at key_store", err)
	}
}
